return {["scripts/actions/spells/blue/lowing.lua"]={["Path"]="scripts/actions/spells/blue/lowing.lua",["SHA256"]="4cab6e407b2001434aa549d27ec4f67566af39fe559ab8a91768d7d3dc9273bf",["Text"]="-----------------------------------\n-- Spell: Lowing\n-- Gives enemies within range a powerful disease that prevents recovery of HP and MP\n-- Spell cost: 66 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 2\n-- Stat Bonus: HP-5\n-- Level: 71\n-- Casting Time: 7 seconds\n-- Recast Time: 56 seconds\n-- Magic Bursts on: Liquefaction, Fusion, and Light\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BEAST\n    params.effect          = xi.effect.PLAGUE\n    params.power           = 5\n    params.tick            = 0\n    params.duration        = 60\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/maelstrom.lua"]={["Path"]="scripts/actions/spells/blue/maelstrom.lua",["SHA256"]="46a56ffeb3abed0b84620318a673bbc0a80a0a565af9403e4d2855f6c01545db",["Text"]="-----------------------------------\n-- Spell: Maelstrom\n-- Deals water damage to enemies within range. Additional effect: STR Down\n-- Spell cost: 162 MP\n-- Monster Type: Aquans\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 5\n-- Stat Bonus: Mind +2\n-- Level: 61\n-- Casting Time: 6 seconds\n-- Recast Time: 39 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.AQUAN\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.WATER\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 2.375\n    params.dStatMultiplier = 1.5\n    params.baseDamageCap   = 69\n\n    params.int_wsc     = 0.3\n    params.mnd_wsc     = 0.1\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STR_DOWN, 20, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/magic_fruit.lua"]={["Path"]="scripts/actions/spells/blue/magic_fruit.lua",["SHA256"]="ef798af2bba0719943ba7d86943a33a82798416e731f97beb5540334c41dccf9",["Text"]="-----------------------------------\n-- Spell: Magic Fruit\n-- Restores HP for the target party member\n-- Spell cost: 72 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 3\n-- Stat Bonus: CHR+1 HP+5\n-- Level: 58\n-- Casting Time: 3.5 seconds\n-- Recast Time: 6 seconds\n-----------------------------------\n-- Combos: Resist Sleep\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params = {}\n\n    params.minCure         = 250\n    params.divisor0        = 0.6666\n    params.constant0       = 130\n    params.powerThreshold1 = 319\n    params.divisor1        = 1\n    params.constant1       = 210\n    params.powerThreshold2 = 559\n    params.divisor2        = 2.8333\n    params.constant2       = 391\n\n    return xi.spells.blue.useCuringSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/magic_hammer.lua"]={["Path"]="scripts/actions/spells/blue/magic_hammer.lua",["SHA256"]="74315d7e86e440847e2588c8d58c707c8c217ae6c2e0457612b1981cd002278e",["Text"]="-----------------------------------\n-- Spell: Magic Hammer\n-- Steals an amount of enemy's MP equal to damage dealt. Ineffective against undead.\n-- Spell cost: 40 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 4\n-- Stat Bonus: MP-5, MND+2\n-- Level: 74\n-- Casting Time: 4 seconds\n-- Recast Time: 180 seconds\n-- Magic Bursts on: Transfixion, Fusion, and Light\n-- Combos: Magic Attack Bonus\n-- Notes:\n-- Modifiers: MND 30%.\n-- Affected by Magic Attack Bonus.\n-- The bonus from Light Staff/Apollo's Staff affects both accuracy and amount of MP drained.\n-- The bonuses from weather/day effects and Korin/Hachirin-no-Obi affect both accuracy and amount of MP drained.\n-- Can only drain MP from targets that have MP and cannot drain more MP than the target has.\n-- Damage and MP drained are enhanced by both Magic Attack Bonus and Magic Attack from Convergence.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params        = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem    = xi.ecosystem.BEASTMEN\n    params.attackType   = xi.attackType.MAGICAL\n    params.damageType   = xi.damageType.LIGHT\n    params.dStat        = xi.mod.MND\n\n    params.ftp0            = 1.5\n    params.azureBonus      = 0.5\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 35\n    params.halfThreshold   = 60\n    params.lowThreshold    = -17\n\n    params.mnd_wsc = 0.3\n\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    local mpDrained = utils.clamp(damage, 0, target:getMP())\n\n    -- Magic Hammer is a damaging spell that also restores MP. There is no messaging about MP restoration.\n    -- Despite this, magic hammer doesn't work on undead.\n    if mpDrained > 0 and not target:isUndead() then\n        caster:addMP(mpDrained)\n        target:delMP(mpDrained)\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/magnetite_cloud.lua"]={["Path"]="scripts/actions/spells/blue/magnetite_cloud.lua",["SHA256"]="3a46c14e13b9abaaa5d0bdc7fd11dd9d71ee4ee1b0aa4482ebfba6d1643606b1",["Text"]="-----------------------------------\n-- Spell: Magnetite Cloud\n-- Deals earth damage to enemies within a fan-shaped area originating from the caster. Additional effect: Weight\n-- Spell cost: 86 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+2\n-- Level: 46\n-- Casting Time: 4.5 seconds\n-- Recast Time: 29.25 seconds\n-- Magic Bursts on: Scission, Gravitation, and Darkness\n-- Combos: Magic Defense Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.BEASTMEN\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.EARTH\n    params.hpMod      = 6\n    params.lvlMod     = 1.875\n    params.isConal    = true\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useBreathSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.WEIGHT, 25, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/mandibular_bite.lua"]={["Path"]="scripts/actions/spells/blue/mandibular_bite.lua",["SHA256"]="f80f579da38eee8babda3e846ead4c1c0cd22acdd274303afdfdf3741f5da4bc",["Text"]="-----------------------------------\n-- Spell: Mandibular Bite\n-- Damage varies with TP\n-- Spell cost: 38 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: INT+1\n-- Level: 44\n-- Casting Time: 0.5 seconds\n-- Recast Time: 19.25 seconds\n-- Skillchain property(ies): Induration\n-- Combos: Plantoid Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.VERMIN\n    params.tpModifier     = xi.spells.blue.tpMod.ATTACK\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.INDURATION\n\n    params.numHits       = 1\n    params.ftp0          = 2.0\n    params.ftp1500       = 2.0\n    params.ftp3000       = 2.0\n    params.ftpAzure      = 2.0\n    params.baseDamageCap = 45\n    params.attackMult    = 1.75\n\n    if params.hasAzureLore then\n        params.attackMult = 2.65\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.75, 2.1, 2.5)\n    end\n\n    params.str_wsc = 0.2\n    params.int_wsc = 0.2\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/memento_mori.lua"]={["Path"]="scripts/actions/spells/blue/memento_mori.lua",["SHA256"]="d6084b67686a7ed730eff9f432114ba401e7996e820c33e0242e09596f4da272",["Text"]="-----------------------------------\n-- Spell: Memento Mori\n-- Enhances magic attack\n-- Spell cost: 46 MP\n-- Monster Type: Undead\n-- Spell Type: Magical (Ice)\n-- Blue Magic Points: 4\n-- Stat Bonus: INT+1\n-- Level: 62\n-- Casting Time: 6 seconds\n-- Recast Time: 2 minutes\n-----------------------------------\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 20\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 60)\n\n    if not target:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.MAGIC_ATK_BOOST\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/metallic_body.lua"]={["Path"]="scripts/actions/spells/blue/metallic_body.lua",["SHA256"]="41b6ed6d7f42d2b44c8a42b8b3a193e47e066fb7aeaca73211dab59f1e13308d",["Text"]="-----------------------------------\n-- Spell: Metallic Body\n-- Absorbs an certain amount of damage from physical and magical attacks\n-- Spell cost: 19 MP\n-- Monster Type: Aquans\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 1\n-- Stat Bonus: None\n-- Level: 8\n-- Casting Time: 7 seconds\n-- Recast Time: 60 seconds\n-- Duration: 5 minutes\n-----------------------------------\n-- Combos: Max MP Boost\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local blueSkill = utils.clamp(caster:getSkillLevel(xi.skill.BLUE_MAGIC), 0, 500)\n    local power     = utils.clamp(0.375 * blueSkill + 12.5, 0, 150)\n    local duration  = xi.spells.blue.calculateDurationWithDiffusion(caster, 300)\n\n    if not target:addStatusEffect(xi.effect.STONESKIN, { power = power, duration = duration, origin = caster, tier = 2 }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.STONESKIN\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/mind_blast.lua"]={["Path"]="scripts/actions/spells/blue/mind_blast.lua",["SHA256"]="b86c8a625d3a16da60da3adff7c2f09fa442b2b67c2d45c66b9ee1a1fe97c88d",["Text"]="-----------------------------------\n-- Spell: Mind Blast\n-- Deals lightning damage to an enemy. Additional effect: Paralysis\n-- Spell cost: 82 MP\n-- Monster Type: Demons\n-- Spell Type: Magical (Lightning)\n-- Blue Magic Points: 4\n-- Stat Bonus: MP+5 MND+1\n-- Level: 73\n-- Casting Time: 3 seconds\n-- Recast Time: 30 seconds\n-- Magic Bursts on: Impaction, Fragmentation, and Light\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.DEMON\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.THUNDER\n    params.dStat       = xi.mod.MND\n\n    params.ftp0            = 2.08\n    params.azureBonus      = 0.5\n    params.dStatMultiplier = 1.5\n    params.baseDamageCap   = 69\n\n    params.mnd_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.PARALYSIS, 20, 0, 90 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/mp_drainkiss.lua"]={["Path"]="scripts/actions/spells/blue/mp_drainkiss.lua",["SHA256"]="362c8926a1dfa330fd812279f2123ca0bd182dd163e39360c58df0e928d7226a",["Text"]="-----------------------------------\n-- Spell: MP Drainkiss\n-- Steals an enemy's MP. Ineffective against undead\n-- Spell cost: 20 MP\n-- Monster Type: Amorphs\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 4\n-- Stat Bonus: MP+5\n-- Level: 42\n-- Casting Time: 4 seconds\n-- Recast Time: 90 seconds\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.AMORPH\n    params.attackType = xi.attackType.MAGICAL\n    params.dStat      = xi.mod.INT\n\n    params.dmgMultiplier = 3.5\n\n    return xi.spells.blue.useDrainSpell(caster, target, spell, params, 165, true)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/mysterious_light.lua"]={["Path"]="scripts/actions/spells/blue/mysterious_light.lua",["SHA256"]="77189a6fbf6c94808970b1da32bb19d2a17ecb661df26096a0d50a7277898867",["Text"]="-----------------------------------\n-- Spell: Mysterious Light\n-- Deals wind damage to enemies within range. Additional effect: Weight\n-- Spell cost: 73 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 4\n-- Stat Bonus: AGI+3\n-- Level: 40\n-- Casting Time: 3.75 seconds\n-- Recast Time: 24.5 seconds\n-- Magic Bursts on: Detonation, Fragmentation, Light\n-- Combos: Max MP Boost\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.ARCANA\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.WIND\n    params.dStat       = xi.mod.CHR\n\n    params.ftp0            = 2.0\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 56\n    params.halfThreshold   = 77\n    params.lowThreshold    = -24\n\n    params.chr_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.WEIGHT, 25, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/occultation.lua"]={["Path"]="scripts/actions/spells/blue/occultation.lua",["SHA256"]="10b6f4acb783c4f36be7e9177faa21a43bf4fdeab0c3bf0e7dd24ab190e2948e",["Text"]="-----------------------------------\n-- Spell: Occultation\n-- Creates shadow images that each absorb a single attack directed at you\n-- Spell cost: 138 MP\n-- Monster Type: Empty\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+3 CHR-2\n-- Level: 88\n-- Casting Time: 2 seconds\n-- Recast Time: 1 minute, 30 seconds\n-----------------------------------\n-- Combos: Evasion Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local skill    = caster:getSkillLevel(xi.skill.BLUE_MAGIC)\n    local power    = skill / 50\n    local duration = 300\n\n    -- 400 skill = 8 shadows, 450 = 9 shadows, so I am assuming every 50 skill is a shadow.\n    -- Also assuming minimum of 2 shadows.\n    -- I've never seen the spell cast with under 100 skill, so I could be wrong.\n    if skill < 100 then\n        power = 2\n    end\n\n    if caster:hasStatusEffect(xi.effect.DIFFUSION) then\n        local diffMerit = caster:getMerit(xi.merit.DIFFUSION)\n\n        if diffMerit > 0 then\n            duration = duration + (duration / 100) * diffMerit\n        end\n\n        caster:delStatusEffect(xi.effect.DIFFUSION)\n    end\n\n    if not target:addStatusEffect(xi.effect.BLINK, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.BLINK\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/pinecone_bomb.lua"]={["Path"]="scripts/actions/spells/blue/pinecone_bomb.lua",["SHA256"]="f2de470c09a5caad811ccec26d0fe6fd0060afc6e020d869b774bc52218872af",["Text"]="-----------------------------------\n-- Spell: Pinecone Bomb\n-- Additional effect: Sleep. Duration of effect varies with TP\n-- Spell cost: 48 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 2\n-- Stat Bonus: STR+1\n-- Level: 36\n-- Casting Time: 2.5 seconds\n-- Recast Time: 26.5 seconds\n-- Skillchain Element(s): Liquefaction\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.PLANTOID\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.RANGED\n    params.damageType     = xi.damageType.PIERCING\n    params.skillchainType = xi.skillchainType.LIQUEFACTION\n\n    params.numHits       = 1\n    params.ftp0          = 2.25\n    params.ftp1500       = 2.25\n    params.ftp3000       = 2.25\n    params.ftpAzure      = 2.25\n    params.baseDamageCap = 37\n\n    params.str_wsc    = 0.2\n    params.agi_wsc    = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    local duration = 90\n\n    -- TODO: 3k/azure lore duration needs verification\n    if params.hasAzureLore then\n        duration = 240\n    elseif params.hasChainAffinity then\n        duration = xi.spells.blue.calculatefTP(caster:getTP(), 90, 150, 210)\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.SLEEP_I, 1, 0, duration },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/plasma_charge.lua"]={["Path"]="scripts/actions/spells/blue/plasma_charge.lua",["SHA256"]="2715e092fe3195a3498196740555f4099bb7148a989da86444e8f368fd8843ca",["Text"]="-----------------------------------\n-- Spell: Plasma Charge\n-- Covers you with magical lightning spikes. Enemies that hit you take lightning damage\n-- Spell cost: 24 MP\n-- Monster Type: Luminians\n-- Spell Type: Magical (Lightning)\n-- Blue Magic Points: 5\n-- Stat Bonus: STR+3 DEX+3\n-- Level: 75\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-- Duration: 60 seconds\n-----------------------------------\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 5 -- 5 dmg\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 60)\n\n    if not target:addStatusEffect(xi.effect.SHOCK_SPIKES, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.SHOCK_SPIKES\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/plenilune_embrace.lua"]={["Path"]="scripts/actions/spells/blue/plenilune_embrace.lua",["SHA256"]="593d62663917e3a425143dcca542b8fa4f6677586b7059a7673f7caa7c02408f",["Text"]="-----------------------------------\n-- Spell: Plenilune Embrace\n-- Restores target party member's HP and enhances attack and magic attack..\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\nrequire('scripts/globals/magic')\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local duration  = 90\n    local moonCycle = getVanadielMoonCycle()\n\n    local cycleBuffs =\n    {\n        [xi.moonCycle.NEW_MOON]                = { atk = 1,  mab = 15 },\n        [xi.moonCycle.LESSER_WAXING_CRESCENT]  = { atk = 3,  mab = 12 },\n        [xi.moonCycle.GREATER_WAXING_CRESCENT] = { atk = 5,  mab = 10 },\n        [xi.moonCycle.FIRST_QUARTER]           = { atk = 7,  mab = 7  },\n        [xi.moonCycle.LESSER_WAXING_GIBBOUS]   = { atk = 10, mab = 5  },\n        [xi.moonCycle.GREATER_WAXING_GIBBOUS]  = { atk = 12, mab = 3  },\n        [xi.moonCycle.FULL_MOON]               = { atk = 15, mab = 1  },\n        [xi.moonCycle.GREATER_WANING_GIBBOUS]  = { atk = 12, mab = 3  },\n        [xi.moonCycle.LESSER_WANING_GIBBOUS]   = { atk = 10, mab = 5  },\n        [xi.moonCycle.THIRD_QUARTER]           = { atk = 7,  mab = 7  },\n        [xi.moonCycle.GREATER_WANING_CRESCENT] = { atk = 5,  mab = 10 },\n        [xi.moonCycle.LESSER_WANING_CRESCENT]  = { atk = 3,  mab = 12 },\n    }\n\n    local moonBuff = cycleBuffs[moonCycle]\n    local atkBoost = moonBuff.atk\n    local mabBoost = moonBuff.mab\n\n    caster:addStatusEffect(xi.effect.ATTACK_BOOST, { power = atkBoost, duration = duration, origin = caster })\n    caster:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { power = mabBoost, duration = duration, origin = caster })\n\n    local minCure = 350\n\n    local divisor = 0.6666\n    local constant = 230\n    local power = getCurePowerOld(caster)\n    if power > 559 then\n        divisor = 2.8333\n        constant = 491.2\n    elseif power > 319 then\n        divisor =  1\n        constant = 310\n    end\n\n    local final = getCureFinal(caster, spell, getBaseCureOld(power, divisor, constant), minCure, true)\n\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n    caster:updateEnmityFromCure(target, final)\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/poison_breath.lua"]={["Path"]="scripts/actions/spells/blue/poison_breath.lua",["SHA256"]="0f96b37df1914697fa3950b0186f3be6b2edbe6094633769cfd693c98822e9cc",["Text"]="-----------------------------------\n-- Spell: Poison Breath\n-- Deals water damage to enemies within a fan-shaped area originating from the caster. Additional effect: Poison\n-- Spell cost: 22 MP\n-- Monster Type: Undead\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 1\n-- Stat Bonus: MND+1\n-- Level: 22\n-- Casting Time: 3 seconds\n-- Recast Time: 19.5 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.UNDEAD\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.WATER\n    params.hpMod      = 10\n    params.lvlMod     = 1.25\n    params.isConal    = true\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useBreathSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.POISON, 4, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/pollen.lua"]={["Path"]="scripts/actions/spells/blue/pollen.lua",["SHA256"]="0066eeb7cc1ac4bfa88b38e91479773ac4ca78452e3741bd8b5a9d6d3e0cc45d",["Text"]="-----------------------------------\n-- Spell: Pollen\n-- Restores HP\n-- Spell cost: 8 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 1\n-- Stat Bonus: CHR+1, HP+5\n-- Level: 1\n-- Casting Time: 2 seconds\n-- Recast Time: 5 seconds\n-----------------------------------\n-- Combos: Resist Sleep\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params = {}\n\n    params.minCure         = 14\n    params.divisor0        = 1\n    params.constant0       = -6\n    params.powerThreshold1 = 59\n    params.divisor1        = 2\n    params.constant1       = 9\n    params.powerThreshold2 = 99\n    params.divisor2        = 57\n    params.constant2       = 33.125\n\n    return xi.spells.blue.useCuringSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/power_attack.lua"]={["Path"]="scripts/actions/spells/blue/power_attack.lua",["SHA256"]="66a4e9baeac2fb1b5740d267b841c6ca5da978d972a9cb84739e1a99e9d1ac9d",["Text"]="-----------------------------------\n-- Spell: Power Attack\n-- Deals critical damage. Chance of critical hit varies with TP\n-- Spell cost: 5 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 1\n-- Stat Bonus: MND+1\n-- Level: 4\n-- Casting Time: 0.5 seconds\n-- Recast Time: 7.25 seconds\n-- Skillchain property: Reverberation\n-- Combos: Plantoid Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.VERMIN\n    params.tpModifier = xi.spells.blue.tpMod.CRITICAL\n\n    if params.hasAzureLore then\n        params.critChance = 35\n    elseif params.hasChainAffinity then\n        params.critChance = xi.spells.blue.calculatefTP(caster:getTP(), 0, 15, 30)\n    end\n\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.REVERBERATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.125\n    params.ftp1500       = 1.125\n    params.ftp3000       = 1.125\n    params.ftpAzure      = 1.125\n    params.baseDamageCap = 11\n    params.attackMult    = 1.8\n\n    params.str_wsc = 0.1\n    params.vit_wsc = 0.1\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/quad_continuum.lua"]={["Path"]="scripts/actions/spells/blue/quad_continuum.lua",["SHA256"]="5a865d6d437cacd1694f61fa4c7d15eaba92732d56b31af61cc1276ea09d0b7b",["Text"]="-----------------------------------\n-- Spell: Quadratic Continuum\n-- Delivers a fourfold attack. Damage varies with TP\n-- Spell cost: 91 MP\n-- Monster Type: Empty\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 4\n-- Stat Bonus: DEX+3 CHR-2\n-- Level: 85\n-- Casting Time: 1 seconds\n-- Recast Time: 31.75 seconds\n-- Skillchain Element(s): Distortion/Scission\n-- Combos: Dual Wield\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.EMPTY\n    params.tpModifier      = xi.spells.blue.tpMod.DAMAGE\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.PIERCING\n    params.skillchainType  = xi.skillchainType.DISTORTION\n    params.skillchainType2 = xi.skillchainType.SCISSION\n\n    params.numHits       = 4\n    params.ftp0          = 1.25\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.75\n    params.ftpAzure      = 2.0\n    params.baseDamageCap = 75\n\n    params.str_wsc = 0.32\n    params.vit_wsc = 0.32\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/quadrastrike.lua"]={["Path"]="scripts/actions/spells/blue/quadrastrike.lua",["SHA256"]="5c6d9d258cb02b4598c310469a0c2dc28dc93ac00bd32c2f9ea431ae444ecdc8",["Text"]="-----------------------------------\n-- Spell: Quadrastrike\n-- Delivers a fourfold attack. Chance of critical hit varies with TP.\n-- Spell cost: 98 MP\n-- Monster Type: Demons\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 5\n-- Stat Bonus: STR+3 CHR+3\n-- Level: 96\n-- Casting Time: 2 seconds\n-- Recast Time: 42.5 seconds\n-- Skillchain Element(s): Liquefaction, Scission\n-- Combos: Sillchain Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    -- Missing proper info and logic for crit.\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.DEMON\n    params.tpModifier = xi.spells.blue.tpMod.CRITICAL\n\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.LIQUEFACTION\n    params.skillchainType2 = xi.skillchainType.SCISSION\n\n    params.numHits       = 4\n    params.ftp0          = 1.1875\n    params.ftp1500       = 1.1875\n    params.ftp3000       = 1.1875\n    params.ftpAzure      = 1.1875\n    params.baseDamageCap = 100\n\n    params.str_wsc = 0.3\n\n    params.critChance = 30 -- Guessed, this probably scales with TP, BG wiki says 33% which likely includes base crit rate so we're reducing it a bit lower\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/queasyshroom.lua"]={["Path"]="scripts/actions/spells/blue/queasyshroom.lua",["SHA256"]="216e4dd777a599a726b0a9ae60dc580f2402a532e653f2f0b856af993fb1612e",["Text"]="-----------------------------------\n-- Spell: Queasyshroom\n-- Additional effect: Poison. Duration of effect varies with TP\n-- Spell cost: 20 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 2\n-- Stat Bonus: HP-5, MP+5\n-- Level: 8\n-- Casting Time: 2 seconds\n-- Recast Time: 15 seconds\n-- Skillchain Element(s): Compression\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.PLANTOID\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.RANGED\n    params.damageType     = xi.damageType.PIERCING\n    params.skillchainType = xi.skillchainType.COMPRESSION\n\n    params.numHits       = 1\n    params.ftp0          = 1.75\n    params.ftp1500       = 1.75\n    params.ftp3000       = 1.75\n    params.ftpAzure      = 1.75\n    params.baseDamageCap = 15\n\n    params.int_wsc = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    local duration = 90\n\n    -- TODO: duration needs verification\n    if params.hasAzureLore then\n        duration = 210\n    elseif params.hasChainAffinity then\n        duration = xi.spells.blue.calculatefTP(caster:getTP(), 90, 150, 180)\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.POISON, 3, 3, duration },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/radiant_breath.lua"]={["Path"]="scripts/actions/spells/blue/radiant_breath.lua",["SHA256"]="3a5136ce66934a002224fc9a9beafd343be6d56d6b69d17bfb2a4efd90da87ce",["Text"]="-----------------------------------\n-- Spell: Radiant Breath\n-- Deals light damage to enemies within a fan-shaped area of effect originating from the caster. Additional effect: Slow and Silence.\n-- Spell cost: 116 MP\n-- Monster Type: Dragons\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 4\n-- Stat Bonus: CHR+1, HP+5\n-- Level: 54\n-- Casting Time: 5.25 seconds\n-- Recast Time: 33.75 seconds\n-- Magic Bursts on: Transfixion, Fusion, Light\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.DRAGON\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.LIGHT\n    params.hpMod      = 5\n    params.lvlMod     = 0.75\n    params.isConal    = true\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useBreathSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.SLOW,    2500, 0, 60 },\n        [2] = { xi.effect.SILENCE,   25, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/ram_charge.lua"]={["Path"]="scripts/actions/spells/blue/ram_charge.lua",["SHA256"]="cb1e845039440ce3aa63ddbf5ef3e481d7815a3b3aeb5f059633a999a0e4e78b",["Text"]="-----------------------------------\n-- Spell: Ram Charge\n-- Damage varies with TP\n-- Spell cost: 79 MP\n-- Monster Type: Beasts\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP+5\n-- Level: 73\n-- Casting Time: 0.5 seconds\n-- Recast Time: 34.75 seconds\n-- Skillchain Element(s): Fragmentation\n-- Combos: Lizard Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEAST\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.FRAGMENTATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.0\n    params.ftp1500       = 1.375\n    params.ftp3000       = 1.75\n    params.ftpAzure      = 1.875\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 2.5\n\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.5\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/reactor_cool.lua"]={["Path"]="scripts/actions/spells/blue/reactor_cool.lua",["SHA256"]="ec7960885fee23813862705cb80b7fe931a1dec1e632d29d91f2a6d58c264a0f",["Text"]="-----------------------------------\n-- Spell: Reactor Cool\n-- Enhances defense and covers you with magical ice spikes. Enemies that hit you take ice damage\n-- Spell cost: 28 MP\n-- Monster Type: Luminions\n-- Spell Type: Magical (Ice)\n-- Blue Magic Points: 5\n-- Stat Bonus: INT+3 MND+3\n-- Level: 74\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-- Duration: 120 seconds (2 minutes)\n-----------------------------------\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 120)\n\n    -- Reactor Cool Will Overwrite Ice Spikes and Def Boost regardless of Power\n    if\n        target:hasStatusEffect(xi.effect.DEFENSE_BOOST) or\n        target:hasStatusEffect(xi.effect.ICE_SPIKES)\n    then\n        target:delStatusEffectSilent(xi.effect.DEFENSE_BOOST)\n        target:delStatusEffectSilent(xi.effect.ICE_SPIKES)\n    end\n\n    target:addStatusEffect(xi.effect.DEFENSE_BOOST, { power = 12, duration = duration, origin = caster })\n    target:addStatusEffect(xi.effect.ICE_SPIKES, { power = 5, duration = duration, origin = caster })\n    spell:setMsg(xi.msg.basic.MAGIC_GAIN_EFFECT)\n\n    return xi.effect.DEFENSE_BOOST\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/refueling.lua"]={["Path"]="scripts/actions/spells/blue/refueling.lua",["SHA256"]="42ae203e33f8077ded3c14bf8cd8302df80a761dcdbfd43d606ecf487c68136b",["Text"]="-----------------------------------\n-- Spell: Refueling\n-- Increases attack speed\n-- Spell cost: 29 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 4\n-- Stat Bonus: AGI+2\n-- Level: 48\n-- Casting Time: 1.5 seconds\n-- Recast Time: 30 seconds\n-- Duration: 5 minutes\n-----------------------------------\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 1000 -- 10%\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 300)\n\n    if not target:addStatusEffect(xi.effect.HASTE, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.HASTE\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/regeneration.lua"]={["Path"]="scripts/actions/spells/blue/regeneration.lua",["SHA256"]="81638ca09ab0ecbce4316db03e679c70543eb11c5058e76363e23655acd409ec",["Text"]="-----------------------------------\n-- Spell: Regeneration\n-- Gradually restores HP\n-- Spell cost: 36 MP\n-- Monster Type: Aquans\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 2\n-- Stat Bonus: MND+2\n-- Level: 78\n-- Casting Time: 2 Seconds\n-- Recast Time: 60 Seconds\n-- Spell Duration: 30 ticks, 90 Seconds\n-----------------------------------\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 25\n    local duration = 90\n\n    if caster:hasStatusEffect(xi.effect.DIFFUSION) then\n        local diffMerit = caster:getMerit(xi.merit.DIFFUSION)\n\n        if diffMerit > 0 then\n            duration = duration + (duration / 100) * diffMerit\n        end\n\n        caster:delStatusEffect(xi.effect.DIFFUSION)\n    end\n\n    if\n        target:hasStatusEffect(xi.effect.REGEN) and\n        target:getStatusEffect(xi.effect.REGEN):getTier() == 1\n    then\n        target:delStatusEffect(xi.effect.REGEN)\n    end\n\n    if not target:addStatusEffect(xi.effect.REGEN, { power = power, duration = duration, origin = caster, tick = 3 }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.REGEN\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/regurgitation.lua"]={["Path"]="scripts/actions/spells/blue/regurgitation.lua",["SHA256"]="054ddbb541fd818350c450a6ecf77e9ff01b8b81d041702097748b2ed8b83180",["Text"]="-----------------------------------\n-- Spell: Regurgitation\n-- Deals Water damage to an enemy. Additional Effect: Bind\n-- Spell cost: 69 MP\n-- Monster Type: Lizards\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 1\n-- Stat Bonus: INT+1 MND+1 MP+3\n-- Level: 68\n-- Casting Time: 5 seconds\n-- Recast Time: 24 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Resist Gravity\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.LIZARD\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.WATER\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 1.83\n    params.dStatMultiplier = 2.0\n    params.baseDamageCap   = 69\n\n    params.mnd_wsc     = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n    if caster:isBehind(target) then\n        damage = math.floor(damage * 1.25)\n    end\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.BIND, 1, 0, 30 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/saline_coat.lua"]={["Path"]="scripts/actions/spells/blue/saline_coat.lua",["SHA256"]="73210bc3dc0f40886c0b730569a0b5ccf94db1a339a8cc6cb21454b20ddb11a7",["Text"]="-----------------------------------\n-- Spell: Saline Coat\n-- Enhances magic defense\n-- Spell cost: 66 MP\n-- Monster Type: Luminians\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+2, AGI+2, MP+10\n-- Level: 72\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-- Duration: 60 seconds\n-----------------------------------\n-- Combos: Defense Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 50\n    local tick     = 4 -- decay by 1 every 4 seconds\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 180)\n\n    if not target:addStatusEffect(xi.effect.MAGIC_DEF_BOOST, { power = power, duration = duration, origin = caster, tick = tick }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.MAGIC_DEF_BOOST\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sandspin.lua"]={["Path"]="scripts/actions/spells/blue/sandspin.lua",["SHA256"]="8b7b4eefd441d5232f19b60f584d3d2537f2312448b2be249268ef055b2ac7f0",["Text"]="-----------------------------------\n-- Spell: Sandspin\n-- Deals earth damage to enemies within range. Additional Effect: Accuracy Down\n-- Spell cost: 10 MP\n-- Monster Type: Amorphs\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 1\n-- Casting Time: 1.5 seconds\n-- Recast Time: 9.75 seconds\n-- Magic Bursts on: Scission, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.AMORPH\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.EARTH\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 1.0\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 13\n    params.halfThreshold   = 16\n    params.lowThreshold    = -6\n\n    params.int_wsc     = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.ACCURACY_DOWN, 25, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sandspray.lua"]={["Path"]="scripts/actions/spells/blue/sandspray.lua",["SHA256"]="7aee474d6d7878f72db81a9376eb4406272c517ae4595414947ca04bb76ee284",["Text"]="-----------------------------------\n-- Spell: Sandspray\n-- Blinds enemies within a fan-shaped area originating from the caster\n-- Spell cost: 43 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 66\n-- Casting Time: 3 seconds\n-- Recast Time: 90 seconds\n-- Magic Bursts on: Compression, Gravitation, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BEASTMEN\n    params.effect          = xi.effect.BLINDNESS\n    params.power           = 25\n    params.tick            = 0\n    params.duration        = 120\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = true\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/screwdriver.lua"]={["Path"]="scripts/actions/spells/blue/screwdriver.lua",["SHA256"]="3b47032a9f013eecd48abc787a51418ae2c3013a024212d3ca8d180dc1af0553",["Text"]="-----------------------------------\n-- Spell: Screwdriver\n-- Deals critical damage. Chance of critical hit varies with TP\n-- Spell cost: 21 MP\n-- Monster Type: Aquans\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+1, CHR+1, HP+10\n-- Level: 26\n-- Casting Time: 0.5 seconds\n-- Recast Time: 14 seconds\n-- Skillchain Element(s): Transfixion/Scission\n-- Combos: Evasion Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params        = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem    = xi.ecosystem.AQUAN\n    params.tpModifier   = xi.spells.blue.tpMod.CRITICAL\n\n    if params.hasAzureLore then\n        params.critChance = 35\n    elseif params.hasChainAffinity then\n        params.critChance = xi.spells.blue.calculatefTP(caster:getTP(), 0, 15, 30)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.PIERCING\n    params.skillchainType  = xi.skillchainType.TRANSFIXION\n    params.skillchainType2 = xi.skillchainType.SCISSION\n\n    params.numHits       = 1\n    params.ftp0          = 1.375\n    params.ftp1500       = 1.375\n    params.ftp3000       = 1.375\n    params.ftpAzure      = 1.375\n    params.baseDamageCap = 27\n    params.attackMult    = 1.6\n\n    params.str_wsc = 0.2\n    params.mnd_wsc = 0.2\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/seedspray.lua"]={["Path"]="scripts/actions/spells/blue/seedspray.lua",["SHA256"]="84437121b24aa353033de7ec9042a412c83e7716a605b31b3e022b33ddfe2b58",["Text"]="-----------------------------------\n-- Spell: Seedspray\n-- Delivers a threefold attack. Additional effect: Weakens defense. Chance of effect varies with TP\n-- Spell cost: 61 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 61\n-- Casting Time: 4 seconds\n-- Recast Time: 35 seconds\n-- Skillchain Element(s): Induration/Detonation\n-- Combos: Beast Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.PLANTOID\n    params.tpModifier      = xi.spells.blue.tpMod.DURATION\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.INDURATION\n    params.skillchainType2 = xi.skillchainType.DETONATION\n\n    params.numHits       = 3\n    params.ftp0          = 0.875\n    params.ftp1500       = 0.875\n    params.ftp3000       = 0.875\n    params.ftpAzure      = 0.875\n    params.baseDamageCap = 999 -- uncapped\n\n    params.dex_wsc    = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.DEFENSE_DOWN, 8, 0, 120 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"}};
